export function createSeoFoundationDrafts() {
  return articles.map(article=>createArticleDraft({
    id:'seo-foundation-'+article.slug,
    slug:article.slug,categoryId:article.categoryId,tags:article.tags,authorName:'CoverMate',
    image:{src:covers[article.categoryId].src},cover:{src:covers[article.categoryId].src},
    translations:{th:{
      title:article.title,excerpt:article.excerpt,seoTitle:article.seoTitle,seoDescription:article.seoDescription,
      coverAlt:covers[article.categoryId].alt,imageAlt:covers[article.categoryId].alt,caption:covers[article.categoryId].caption,
      headerNoteEnabled:false,sidebarQuoteEnabled:false,takeawayNoteEnabled:false,
      takeaways:[],sources:article.sources,document:document(article.content)
    }}
  }));
}
